-- 099: 角色化首页组件配置与业务催办。
-- 只保存配置、待办提醒和审计事实；不生成伪造的统计结果或消息发送回执。
BEGIN;

CREATE TABLE IF NOT EXISTS "首页组件配置" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "角色名称" varchar(100) NOT NULL DEFAULT '默认',
    "组件编码" varchar(80) NOT NULL,
    "组件标题" varchar(200) NOT NULL,
    "组件类型" varchar(40) NOT NULL DEFAULT '指标卡片',
    "排序号" integer NOT NULL DEFAULT 0,
    "是否启用" boolean NOT NULL DEFAULT TRUE,
    "配置" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "创建人编号" integer REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_首页组件配置_角色编码" UNIQUE ("角色名称", "组件编码"),
    CONSTRAINT "ck_首页组件配置_类型" CHECK ("组件类型" IN ('指标卡片','待办列表','统计图','快捷入口','通知列表')),
    CONSTRAINT "ck_首页组件配置_排序" CHECK ("排序号" >= 0)
);
CREATE INDEX IF NOT EXISTS "ix_首页组件配置_角色状态" ON "首页组件配置" ("角色名称", "是否启用", "排序号");

CREATE TABLE IF NOT EXISTS "业务催办" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "目标人员编号" integer REFERENCES "人员"("编号"),
    "目标角色名称" varchar(100),
    "业务类型" varchar(80) NOT NULL,
    "业务编号" bigint,
    "标题" varchar(300) NOT NULL,
    "催办说明" varchar(2000),
    "截止时间" timestamp without time zone,
    "状态" varchar(20) NOT NULL DEFAULT '待处理',
    "发起人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "处理人编号" integer REFERENCES "人员"("编号"),
    "处理说明" varchar(2000),
    "处理时间" timestamp without time zone,
    "最后提醒时间" timestamp without time zone,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_业务催办_目标" CHECK ("目标人员编号" IS NOT NULL OR NULLIF(trim("目标角色名称"), '') IS NOT NULL),
    CONSTRAINT "ck_业务催办_状态" CHECK ("状态" IN ('待处理','已读','已处理','已取消','已过期')),
    CONSTRAINT "ck_业务催办_处理" CHECK (("状态" IN ('已处理','已取消') AND "处理时间" IS NOT NULL AND "处理人编号" IS NOT NULL) OR "状态" NOT IN ('已处理','已取消'))
);
CREATE INDEX IF NOT EXISTS "ix_业务催办_目标状态" ON "业务催办" ("目标人员编号", "目标角色名称", "状态", "截止时间");
CREATE INDEX IF NOT EXISTS "ix_业务催办_业务" ON "业务催办" ("业务类型", "业务编号", "创建时间" DESC);

CREATE TABLE IF NOT EXISTS "首页配置审计" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "对象类型" varchar(30) NOT NULL,
    "对象编号" bigint,
    "操作类型" varchar(30) NOT NULL,
    "操作人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "变更前" jsonb,
    "变更后" jsonb,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_首页配置审计_对象" ON "首页配置审计" ("对象类型", "对象编号", "创建时间" DESC);

INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (209, 2, '首页组件与业务催办', '科研办公/科研办公/首页组件与业务催办.html', TRUE, '按角色配置首页组件、业务催办和审计')
ON CONFLICT ("编号") DO UPDATE SET "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "备注"=EXCLUDED."备注";
INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 209 FROM "角色" r
WHERE r."名称" IN ('系统管理员','科研管理员','科技办')
  AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=209);

UPDATE "系统迁移版本"
SET "版本"=99, "脚本"='099_dashboard_component_and_chase.sql',
    "检查摘要"='增加角色化首页组件、业务催办和配置审计', "应用时间"=CURRENT_TIMESTAMP
WHERE "编号"=1;

COMMIT;
